<!DOCTYPE html>
<html lang="ro">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover" />
  <meta name="robots" content="noindex,nofollow" />
  <meta name="theme-color" content="#061a15" />
  <title>Pădurea care se răcorește singură — Nordvale</title>
  <meta name="description" content="Articol dummy Nordvale despre microclimatul nucleului protejat și observațiile rangerilor." />
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Fraunces:opsz,wght@9..144,500;9..144,600;9..144,700&display=swap" rel="stylesheet">
  <style>
    :root{
      --pine:#09251d;--pine-dark:#061a15;--pine-mid:#123b30;--pine-light:#1b5242;
      --acid:#dffc62;--ember:#f27b4a;--cream:#fffdf6;--oat:#f0ecdf;--ink:#16231e;
      --moss:#b7c9a3;--sky:#b8dce0;--line:rgba(9,37,29,.12);
      --shadow:0 36px 100px -38px rgba(6,26,21,.58);--card-shadow:0 18px 48px -28px rgba(6,26,21,.46)
    }
    *{box-sizing:border-box}
    html{scroll-behavior:smooth;background:var(--oat)}
    body{margin:0;overflow-x:hidden;background:var(--oat);color:var(--ink);font-family:'DM Sans',sans-serif;text-rendering:optimizeLegibility}
    body.menu-open,body.modal-open{overflow:hidden}
    button,a,input{font:inherit}button{cursor:pointer}a{text-decoration:none;color:inherit}img{display:block;max-width:100%}
    ::selection{background:var(--acid);color:var(--pine-dark)}
    .display{font-family:'Fraunces',serif}.wrap{width:min(1460px,calc(100% - 32px));margin-inline:auto}.article-wrap{width:min(820px,calc(100% - 32px));margin-inline:auto}
    .safe-top{padding-top:max(10px,env(safe-area-inset-top))}.safe-bottom{padding-bottom:max(16px,env(safe-area-inset-bottom))}
    .eyebrow{font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.24em;color:var(--ember)}
    .eyebrow.light{color:var(--acid)}.muted{color:rgba(9,37,29,.62)}.muted-light{color:rgba(255,255,255,.62)}
    .title-xl{font-family:'Fraunces',serif;font-size:clamp(49px,8vw,112px);line-height:.88;letter-spacing:-.058em;font-weight:600;margin:0}
    .title-lg{font-family:'Fraunces',serif;font-size:clamp(39px,6vw,78px);line-height:.94;letter-spacing:-.048em;font-weight:600;margin:0}
    .title-md{font-family:'Fraunces',serif;font-size:clamp(31px,4vw,54px);line-height:.98;letter-spacing:-.04em;font-weight:600;margin:0}
    .btn{display:inline-flex;align-items:center;justify-content:center;gap:9px;min-height:50px;border-radius:999px;padding:0 21px;border:0;font-weight:700;white-space:nowrap;transition:.25s ease}
    .btn:hover{transform:translateY(-2px)}.btn-acid{background:var(--acid);color:var(--pine-dark);box-shadow:0 18px 54px -24px rgba(223,252,98,.58)}
    .btn-dark{background:var(--pine);color:white}.btn-outline{border:1px solid rgba(9,37,29,.2);background:transparent;color:var(--pine)}.btn-ghost{border:1px solid rgba(255,255,255,.2);background:transparent;color:white}
    .icon-btn{width:46px;height:46px;border-radius:50%;display:grid;place-items:center;border:1px solid var(--line);background:var(--cream);color:var(--pine);transition:.2s}.icon-btn:hover{transform:translateY(-2px);border-color:rgba(9,37,29,.28)}
    .grain::after{content:"";position:absolute;inset:0;pointer-events:none;z-index:3;opacity:.075;mix-blend-mode:soft-light;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.82' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.58'/%3E%3C/svg%3E")}
    .topo-dark{background-image:radial-gradient(circle at 18% 22%,rgba(223,252,98,.14),transparent 20%),radial-gradient(circle at 84% 18%,rgba(242,123,74,.12),transparent 17%),url("data:image/svg+xml,%3Csvg width='820' height='820' viewBox='0 0 820 820' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' stroke='%23ffffff' stroke-opacity='.055' stroke-width='1.1'%3E%3Cpath d='M88 212c37-105 158-179 273-133 94 37 117 148 65 224-49 72-150 69-199 143-51 77-34 200-133 247-95 45-205-31-192-137 13-103 118-121 127-216 5-55-2-92 59-128Z'/%3E%3Cpath d='M119 231c31-83 127-143 219-107 76 30 95 118 53 180-40 58-121 56-160 115-42 61-28 159-107 197-77 37-165-25-154-110 10-83 94-98 102-174 4-44 0-74 47-101Z'/%3E%3Cpath d='M513 479c52-81 159-106 232-43 72 60 50 172-26 217-68 40-149 11-202 68-45 48-39 134-105 151-74 19-142-53-112-125 28-67 109-63 148-123 31-49 30-97 65-145Z'/%3E%3C/g%3E%3C/svg%3E");background-size:auto,auto,820px 820px}
    .paper-grid{background-image:linear-gradient(rgba(9,37,29,.052) 1px,transparent 1px),linear-gradient(90deg,rgba(9,37,29,.052) 1px,transparent 1px);background-size:30px 30px}
    .progress{position:fixed;left:0;right:0;top:0;height:3px;z-index:190}.progress>span{display:block;width:100%;height:100%;background:var(--acid);transform-origin:left;transform:scaleX(0)}

    /* Header */
    .site-header{position:fixed;inset:0 0 auto;z-index:170;padding-inline:10px}.nav{max-width:1540px;margin:2px auto 0;min-height:62px;display:flex;align-items:center;justify-content:space-between;gap:8px;border:1px solid transparent;border-radius:20px;padding:10px 12px;transition:.4s ease}
    .nav.scrolled{background:rgba(6,26,21,.82);border-color:rgba(255,255,255,.12);box-shadow:0 24px 70px -42px rgba(0,0,0,.9);backdrop-filter:blur(22px) saturate(130%)}
    .brand{display:flex;align-items:center;gap:10px;min-width:0;color:white}.brand-mark{width:40px;height:40px;border-radius:14px;border:1px solid rgba(255,255,255,.2);background:rgba(255,255,255,.1);display:grid;place-items:center;flex:none}
    .brand-name{font-family:'Fraunces',serif;font-size:19px;font-weight:600;line-height:1;white-space:nowrap}.brand-sub{display:none;margin-top:5px;font-size:7px;font-weight:700;text-transform:uppercase;letter-spacing:.25em;color:rgba(255,255,255,.52);white-space:nowrap}
    .desktop-nav{display:none;align-items:center;gap:27px}.desktop-nav a{font-size:14px;font-weight:600;color:rgba(255,255,255,.7);transition:.2s}.desktop-nav a:hover,.desktop-nav a.active{color:var(--acid)}
    .nav-actions{display:flex;align-items:center;gap:6px;flex:none}.account-link{display:none;color:rgba(255,255,255,.82);font-size:14px;font-weight:600;border:1px solid rgba(255,255,255,.15);padding:10px 16px;border-radius:999px}
    .ticket-btn{min-height:40px;padding:0 13px;font-size:12px}.menu-btn{width:40px;height:40px;border-radius:50%;border:1px solid rgba(255,255,255,.15);background:transparent;color:white;display:grid;place-items:center}
    .mobile-menu{position:fixed;inset:0;z-index:180;visibility:hidden;pointer-events:none}.mobile-menu.open{visibility:visible;pointer-events:auto}.menu-backdrop{position:absolute;inset:0;background:rgba(6,26,21,.74);backdrop-filter:blur(7px);opacity:0;transition:.3s}.mobile-menu.open .menu-backdrop{opacity:1}
    .menu-panel{position:absolute;right:0;top:0;height:100%;width:min(88vw,430px);background:var(--cream);padding:22px;display:flex;flex-direction:column;transform:translateX(100%);transition:.42s cubic-bezier(.2,.8,.2,1)}.mobile-menu.open .menu-panel{transform:none}
    .menu-head{display:flex;align-items:center;justify-content:space-between}.menu-links{margin-top:45px}.menu-links a{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);padding:16px 0;font-family:'Fraunces',serif;font-size:27px;font-weight:600;color:var(--pine)}
    .menu-status{margin-top:auto;background:var(--pine);border-radius:22px;padding:20px;color:white}.status-dot{width:8px;height:8px;border-radius:50%;background:var(--acid);display:inline-block;box-shadow:0 0 0 0 rgba(223,252,98,.45);animation:pulse 2.2s infinite}@keyframes pulse{70%{box-shadow:0 0 0 10px rgba(223,252,98,0)}}

    /* Hero */
    .article-hero{position:relative;min-height:92svh;background:var(--pine-dark);color:white;overflow:hidden;display:flex;align-items:flex-end}
    .hero-media{position:absolute;inset:0}.hero-media img{width:100%;height:100%;object-fit:cover;object-position:center 40%;opacity:.63;transform:scale(1.035)}
    .hero-media::after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(6,26,21,.94) 0%,rgba(6,26,21,.72) 45%,rgba(6,26,21,.18) 100%),linear-gradient(0deg,rgba(6,26,21,.94) 0%,rgba(6,26,21,.18) 57%,rgba(6,26,21,.36) 100%)}
    .hero-route{position:absolute;right:-90px;top:9%;width:670px;height:670px;z-index:2;opacity:.72}.hero-route path{fill:none;stroke:var(--acid);stroke-width:2;stroke-linecap:round;stroke-dasharray:10 14}.hero-route circle{fill:var(--acid)}
    .hero-inner{position:relative;z-index:5;padding:130px 0 48px}.breadcrumbs{display:flex;gap:8px;align-items:center;flex-wrap:wrap;font-size:11px;color:rgba(255,255,255,.52);margin-bottom:26px}.breadcrumbs a:hover{color:var(--acid)}
    .hero-copy{max-width:1040px}.hero-tag{display:inline-flex;align-items:center;gap:9px;padding:9px 13px;border-radius:999px;border:1px solid rgba(255,255,255,.15);background:rgba(255,255,255,.07);font-size:9px;font-weight:700;text-transform:uppercase;letter-spacing:.2em;color:var(--acid)}
    .hero-title{margin-top:22px}.hero-deck{max-width:730px;margin:24px 0 0;font-size:clamp(17px,2vw,23px);line-height:1.55;color:rgba(255,255,255,.72)}
    .article-meta{display:flex;gap:14px;align-items:center;flex-wrap:wrap;margin-top:29px;font-size:11px;text-transform:uppercase;letter-spacing:.13em;color:rgba(255,255,255,.55)}.article-meta strong{color:white;font-weight:700}
    .author-chip{display:flex;align-items:center;gap:10px}.author-chip img{width:42px;height:42px;border-radius:50%;object-fit:cover;border:2px solid rgba(255,255,255,.25)}
    .hero-tools{display:flex;align-items:center;gap:8px;margin-top:28px;flex-wrap:wrap}.hero-tools .icon-btn{background:rgba(255,255,255,.08);border-color:rgba(255,255,255,.16);color:white}
    .scroll-cue{position:absolute;right:20px;bottom:22px;z-index:6;display:none;align-items:center;gap:10px;color:rgba(255,255,255,.55);font-size:9px;text-transform:uppercase;letter-spacing:.19em;transform:rotate(90deg);transform-origin:right bottom}.scroll-cue span{width:52px;height:1px;background:rgba(255,255,255,.35)}

    /* Article */
    .article-shell{position:relative;padding:74px 0 105px}.article-layout{display:grid;gap:34px}.article-sidebar{display:none}.article-body{min-width:0}
    .lead{font-family:'Fraunces',serif;font-size:clamp(24px,3.1vw,36px);line-height:1.35;letter-spacing:-.02em;color:var(--pine);margin:0 0 42px}
    .article-body p{font-size:17px;line-height:1.88;color:rgba(22,35,30,.82);margin:0 0 27px}.article-body h2{font-family:'Fraunces',serif;font-size:clamp(32px,4.3vw,52px);line-height:1.02;letter-spacing:-.04em;color:var(--pine);margin:72px 0 24px}.article-body h3{font-family:'Fraunces',serif;font-size:29px;line-height:1.1;color:var(--pine);margin:48px 0 18px}
    .article-body a{color:var(--pine);text-decoration:underline;text-decoration-color:var(--ember);text-underline-offset:4px}.dropcap:first-letter{float:left;font-family:'Fraunces',serif;font-size:84px;line-height:.78;padding:11px 13px 3px 0;color:var(--ember)}
    .figure{margin:50px 0}.figure img{width:100%;border-radius:30px;aspect-ratio:16/10;object-fit:cover;box-shadow:var(--shadow)}.caption{display:flex;justify-content:space-between;gap:18px;margin-top:12px;font-size:11px;line-height:1.55;color:rgba(9,37,29,.48)}
    .pullquote{position:relative;margin:64px 0;padding:36px 28px 36px 38px;background:var(--pine);color:white;border-radius:30px;overflow:hidden}.pullquote::before{content:'“';position:absolute;right:20px;top:-22px;font-family:'Fraunces',serif;font-size:180px;line-height:1;color:rgba(223,252,98,.12)}
    .pullquote blockquote{position:relative;margin:0;font-family:'Fraunces',serif;font-size:clamp(28px,4vw,46px);line-height:1.12;letter-spacing:-.035em}.pullquote cite{position:relative;display:block;margin-top:20px;font-style:normal;font-size:11px;text-transform:uppercase;letter-spacing:.16em;color:var(--acid)}
    .data-card{margin:56px 0;border:1px solid var(--line);border-radius:30px;background:var(--cream);padding:25px;box-shadow:var(--card-shadow)}.data-head{display:flex;justify-content:space-between;gap:18px;align-items:flex-start;margin-bottom:24px}.data-head h3{margin:0;font-size:29px}.data-badge{padding:8px 11px;border-radius:999px;background:rgba(242,123,74,.12);font-size:9px;font-weight:700;text-transform:uppercase;letter-spacing:.15em;color:var(--ember);white-space:nowrap}
    .temp-chart{height:280px;display:flex;align-items:flex-end;gap:8px;padding:20px 10px 4px;border-bottom:1px solid var(--line);position:relative}.temp-chart::before,.temp-chart::after{content:"";position:absolute;left:0;right:0;border-top:1px dashed rgba(9,37,29,.12)}.temp-chart::before{top:34%}.temp-chart::after{top:66%}
    .bar-group{flex:1;display:flex;align-items:flex-end;justify-content:center;gap:4px;height:100%;position:relative;z-index:2}.bar{width:min(24px,42%);border-radius:8px 8px 3px 3px;transform-origin:bottom;transform:scaleY(0);transition:transform .8s cubic-bezier(.2,.8,.2,1)}.bar.edge{background:var(--ember)}.bar.core{background:var(--pine-light)}.bar-group small{position:absolute;bottom:-29px;font-size:9px;color:rgba(9,37,29,.48)}
    .chart-legend{display:flex;gap:18px;flex-wrap:wrap;margin-top:40px;font-size:11px;color:rgba(9,37,29,.6)}.chart-legend span{display:flex;gap:7px;align-items:center}.legend-dot{width:10px;height:10px;border-radius:3px}.legend-dot.edge{background:var(--ember)}.legend-dot.core{background:var(--pine-light)}
    .fact-grid{display:grid;gap:12px;margin:46px 0}.fact{border-radius:24px;padding:22px;background:var(--cream);border:1px solid var(--line)}.fact strong{display:block;font-family:'Fraunces',serif;font-size:36px;color:var(--pine);line-height:1}.fact span{display:block;margin-top:9px;font-size:12px;line-height:1.55;color:rgba(9,37,29,.58)}
    .gallery{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:58px 0}.gallery button{border:0;padding:0;background:transparent;border-radius:22px;overflow:hidden;position:relative}.gallery button:first-child{grid-column:1/-1}.gallery img{width:100%;height:100%;aspect-ratio:4/3;object-fit:cover;transition:.45s}.gallery button:first-child img{aspect-ratio:16/9}.gallery button:hover img{transform:scale(1.035)}.gallery span{position:absolute;left:12px;bottom:12px;background:rgba(6,26,21,.72);color:white;padding:7px 10px;border-radius:999px;font-size:9px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;backdrop-filter:blur(10px)}
    .note{margin:46px 0;padding:24px 24px 24px 26px;border-left:4px solid var(--acid);background:rgba(223,252,98,.2);border-radius:0 24px 24px 0}.note strong{font-family:'Fraunces',serif;font-size:22px;color:var(--pine)}.note p{margin:9px 0 0;font-size:14px;line-height:1.7}
    .article-tags{display:flex;gap:8px;flex-wrap:wrap;margin-top:54px;padding-top:27px;border-top:1px solid var(--line)}.tag{padding:9px 12px;border-radius:999px;background:var(--cream);border:1px solid var(--line);font-size:10px;font-weight:700;color:rgba(9,37,29,.65)}
    .author-card{margin-top:44px;display:grid;gap:20px;background:var(--pine);color:white;border-radius:30px;padding:25px;overflow:hidden;position:relative}.author-card::after{content:"";position:absolute;width:180px;height:180px;border-radius:50%;right:-70px;top:-80px;background:rgba(223,252,98,.1)}.author-card img{width:90px;height:90px;border-radius:26px;object-fit:cover}.author-card h3{margin:0;font-family:'Fraunces',serif;font-size:28px}.author-card p{margin:8px 0 0;color:rgba(255,255,255,.64);font-size:14px;line-height:1.65}.author-card a{display:inline-flex;margin-top:14px;color:var(--acid);font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.14em;text-decoration:none}
    .share-rail{position:sticky;top:105px;display:grid;gap:10px}.share-label{font-size:8px;text-transform:uppercase;letter-spacing:.2em;color:rgba(9,37,29,.42);writing-mode:vertical-rl;transform:rotate(180deg);margin:0 auto 5px}

    /* Operational and related */
    .operational{background:var(--pine);color:white;padding:76px 0}.operational-grid{display:grid;gap:30px}.operational-card{border:1px solid rgba(255,255,255,.13);border-radius:28px;padding:24px;background:rgba(255,255,255,.055)}.operational-card h3{margin:0;font-family:'Fraunces',serif;font-size:27px}.operational-card p{margin:10px 0 0;color:rgba(255,255,255,.62);font-size:14px;line-height:1.7}.op-status{display:flex;gap:9px;align-items:center;margin-top:18px;font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.14em;color:var(--acid)}
    .related{padding:92px 0 110px}.related-head{display:flex;justify-content:space-between;gap:25px;align-items:end;margin-bottom:34px}.related-grid{display:grid;gap:14px}.story{background:var(--cream);border-radius:28px;overflow:hidden;border:1px solid var(--line);transition:.28s;box-shadow:var(--card-shadow)}.story:hover{transform:translateY(-5px)}.story img{width:100%;aspect-ratio:16/10;object-fit:cover}.story-body{padding:22px}.story-meta{display:flex;justify-content:space-between;gap:10px;font-size:9px;text-transform:uppercase;letter-spacing:.14em;color:rgba(9,37,29,.48)}.story-tag{color:var(--ember);font-weight:700}.story h3{margin:14px 0 8px;font-family:'Fraunces',serif;font-size:26px;line-height:1.08;color:var(--pine)}.story p{margin:0;font-size:13px;line-height:1.65;color:rgba(9,37,29,.58)}
    .newsletter{position:relative;background:var(--acid);padding:64px 0;overflow:hidden}.newsletter-grid{display:grid;gap:24px;align-items:center}.newsletter-form{display:grid;gap:9px}.newsletter-form input{min-height:55px;border:1px solid rgba(9,37,29,.18);border-radius:999px;padding:0 19px;background:rgba(255,255,255,.67);outline:none}.newsletter-form input:focus{border-color:var(--pine)}.newsletter-note{font-size:10px;color:rgba(9,37,29,.54);margin:0}

    /* Footer */
    footer{background:var(--pine-dark);color:white;padding:64px 0 27px}.footer-grid{display:grid;gap:36px}.footer-brand p{max-width:390px;color:rgba(255,255,255,.55);line-height:1.7;font-size:14px}.footer-links{display:grid;grid-template-columns:1fr 1fr;gap:28px}.footer-col strong{font-size:10px;text-transform:uppercase;letter-spacing:.18em;color:var(--acid)}.footer-col a{display:block;margin-top:13px;color:rgba(255,255,255,.58);font-size:13px}.footer-bottom{display:flex;flex-direction:column;gap:12px;margin-top:44px;padding-top:22px;border-top:1px solid rgba(255,255,255,.1);font-size:11px;color:rgba(255,255,255,.38)}

    /* Modal / Toast */
    .modal{position:fixed;inset:0;z-index:220;display:grid;place-items:center;padding:16px;visibility:hidden;pointer-events:none}.modal.open{visibility:visible;pointer-events:auto}.modal-backdrop{position:absolute;inset:0;background:rgba(6,26,21,.82);backdrop-filter:blur(8px);opacity:0;transition:.25s}.modal.open .modal-backdrop{opacity:1}.modal-card{position:relative;width:min(900px,100%);max-height:90svh;overflow:auto;background:var(--cream);border-radius:28px;padding:18px;transform:translateY(20px) scale(.98);opacity:0;transition:.3s}.modal.open .modal-card{transform:none;opacity:1}.modal-image{width:100%;max-height:70svh;object-fit:contain;border-radius:20px;background:var(--pine-dark)}.modal-head{display:flex;justify-content:space-between;gap:15px;align-items:center;margin-bottom:13px}.modal-close{width:42px;height:42px;border-radius:50%;border:1px solid var(--line);background:white;display:grid;place-items:center}
    .share-modal{width:min(480px,100%)}.share-options{display:grid;grid-template-columns:1fr 1fr;gap:10px}.share-option{border:1px solid var(--line);background:white;border-radius:18px;padding:15px;text-align:left;font-weight:700;color:var(--pine)}.copy-box{display:flex;gap:8px;margin-top:18px}.copy-box input{min-width:0;flex:1;border:1px solid var(--line);border-radius:14px;padding:0 12px;background:white;color:rgba(9,37,29,.65)}
    .toast{position:fixed;left:50%;bottom:calc(18px + env(safe-area-inset-bottom));z-index:240;transform:translate(-50%,25px);opacity:0;pointer-events:none;background:var(--pine-dark);color:white;border-radius:999px;padding:12px 17px;font-size:12px;font-weight:700;box-shadow:var(--shadow);transition:.28s;white-space:nowrap}.toast.show{transform:translate(-50%,0);opacity:1}

    [data-reveal]{opacity:0;transform:translateY(20px)}
    @media (prefers-reduced-motion:reduce){html{scroll-behavior:auto}*,*::before,*::after{animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important}[data-reveal]{opacity:1!important;transform:none!important}}

    @media(min-width:640px){
      .wrap{width:min(1460px,calc(100% - 48px))}.article-wrap{width:min(820px,calc(100% - 48px))}.brand-sub{display:block}.ticket-btn{padding:0 17px;font-size:13px}.fact-grid{grid-template-columns:repeat(3,1fr)}.gallery{gap:14px}.author-card{grid-template-columns:auto 1fr;align-items:center}.newsletter-form{grid-template-columns:1fr auto}.footer-bottom{flex-direction:row;justify-content:space-between}.related-grid{grid-template-columns:repeat(2,1fr)}
    }
