            <span>29 iulie 2026</span><span>6 min lectură</span><span>Actualizat 11:40</span>
          </div>
          <div class="hero-tools" data-reveal><button class="icon-btn" id="shareOpen" type="button" aria-label="Distribuie articolul"><svg width="19" height="19" viewBox="0 0 24 24" fill="none"><circle cx="18" cy="5" r="2.4" stroke="currentColor" stroke-width="1.6"/><circle cx="6" cy="12" r="2.4" stroke="currentColor" stroke-width="1.6"/><circle cx="18" cy="19" r="2.4" stroke="currentColor" stroke-width="1.6"/><path d="m8.2 10.9 7.5-4.5M8.2 13.1l7.5 4.5" stroke="currentColor" stroke-width="1.6"/></svg></button><button class="icon-btn" id="copyLinkHero" type="button" aria-label="Copiază linkul"><svg width="19" height="19" viewBox="0 0 24 24" fill="none"><path d="M9.7 14.3 14.3 9.7M7.1 16.9 5.7 18.3a3.5 3.5 0 0 1-5-5l3.6-3.6a3.5 3.5 0 0 1 5 0M16.9 7.1l1.4-1.4a3.5 3.5 0 1 1 5 5l-3.6 3.6a3.5 3.5 0 0 1-5 0" transform="translate(-.5)" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/></svg></button><a class="btn btn-ghost" href="#articol">Începe lectura</a></div>
