      const reduceMotion=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      let toastTimer;

      const showToast=(message)=>{clearTimeout(toastTimer);toast.textContent=message;toast.classList.add('show');toastTimer=setTimeout(()=>toast.classList.remove('show'),2600)};
      const setMenu=(open)=>{mobileMenu.classList.toggle('open',open);mobileMenu.setAttribute('aria-hidden',String(!open));body.classList.toggle('menu-open',open)};
      menuOpen?.addEventListener('click',()=>setMenu(true));menuClose?.addEventListener('click',()=>setMenu(false));menuBackdrop?.addEventListener('click',()=>setMenu(false));

      const updateScroll=()=>{
        nav?.classList.toggle('scrolled',window.scrollY>26);
        const max=document.documentElement.scrollHeight-window.innerHeight;
        progress.style.transform=`scaleX(${max>0?Math.min(1,window.scrollY/max):0})`;
      };
      updateScroll();window.addEventListener('scroll',updateScroll,{passive:true});

      const revealItems=[...document.querySelectorAll('[data-reveal]')];
      if(reduceMotion){revealItems.forEach(el=>{el.style.opacity='1';el.style.transform='none'})}
      else{
        const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.animate([{opacity:0,transform:'translateY(20px)'},{opacity:1,transform:'translateY(0)'}],{duration:720,easing:'cubic-bezier(.2,.8,.2,1)',fill:'forwards'});observer.unobserve(entry.target)}}),{threshold:.13});
        revealItems.forEach(el=>observer.observe(el));
      }

      if(!reduceMotion){
        const path=document.getElementById('heroPath');const marker=document.getElementById('heroMarker');
        if(path&&marker&&path.getTotalLength){const len=path.getTotalLength();let start;
          const tick=(time)=>{start??=time;const t=((time-start)%9000)/9000;const p=path.getPointAtLength(len*t);marker.setAttribute('cx',p.x);marker.setAttribute('cy',p.y);requestAnimationFrame(tick)};requestAnimationFrame(tick)}
        const chart=document.getElementById('tempChart');
        if(chart){const chartObs=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){chart.querySelectorAll('.bar').forEach((bar,i)=>setTimeout(()=>bar.style.transform='scaleY(1)',i*90));chartObs.disconnect()}}),{threshold:.35});chartObs.observe(chart)}
      }else document.querySelectorAll('.bar').forEach(bar=>bar.style.transform='scaleY(1)');

      const modalEls=[...document.querySelectorAll('.modal')];
      const openModal=(id)=>{const modal=document.getElementById(id);if(!modal)return;modal.classList.add('open');modal.setAttribute('aria-hidden','false');body.classList.add('modal-open')};
      const closeModal=(id)=>{const modal=document.getElementById(id);if(!modal)return;modal.classList.remove('open');modal.setAttribute('aria-hidden','true');if(!modalEls.some(m=>m.classList.contains('open')))body.classList.remove('modal-open')};
      document.querySelectorAll('[data-close-modal]').forEach(btn=>btn.addEventListener('click',()=>closeModal(btn.dataset.closeModal)));
      document.addEventListener('keydown',e=>{if(e.key==='Escape'){setMenu(false);modalEls.forEach(m=>closeModal(m.id))}});

      const gallery=[
        {src:'https://images.unsplash.com/photo-1473448912268-2022ce9509d8?auto=format&fit=crop&w=2000&q=90',title:'Coridorul umed'},
        {src:'https://images.unsplash.com/photo-1511497584788-876760111969?auto=format&fit=crop&w=1800&q=90',title:'North Grove'},
        {src:'https://images.unsplash.com/photo-1441974231531-c6227db76b6e?auto=format&fit=crop&w=1800&q=90',title:'Zona tampon'}
      ];
      document.querySelectorAll('[data-gallery]').forEach(btn=>btn.addEventListener('click',()=>{const item=gallery[Number(btn.dataset.gallery)];if(!item)return;document.getElementById('galleryImage').src=item.src;document.getElementById('galleryTitle').textContent=item.title;openModal('galleryModal')}));

      const currentUrl=location.href;
      const shareUrl=document.getElementById('shareUrl');if(shareUrl)shareUrl.value=currentUrl;
      const openShare=()=>openModal('shareModal');
      document.getElementById('shareOpen')?.addEventListener('click',openShare);document.querySelectorAll('.share-trigger').forEach(btn=>btn.addEventListener('click',openShare));
      const copyText=async(text)=>{try{await navigator.clipboard.writeText(text);showToast('Link copiat în clipboard.')}catch{const temp=document.createElement('textarea');temp.value=text;document.body.appendChild(temp);temp.select();document.execCommand('copy');temp.remove();showToast('Link copiat în clipboard.')}};
      document.getElementById('copyLinkHero')?.addEventListener('click',()=>copyText(currentUrl));document.querySelectorAll('.copy-trigger').forEach(btn=>btn.addEventListener('click',()=>copyText(currentUrl)));document.getElementById('copyShareUrl')?.addEventListener('click',()=>copyText(currentUrl));
      document.querySelectorAll('[data-share]').forEach(btn=>btn.addEventListener('click',async()=>{const type=btn.dataset.share;const title=document.title;if(type==='native'&&navigator.share){try{await navigator.share({title,url:currentUrl})}catch{}return}if(type==='email'){location.href=`mailto:?subject=${encodeURIComponent(title)}&body=${encodeURIComponent(currentUrl)}`;return}if(type==='whatsapp'){window.open(`https://wa.me/?text=${encodeURIComponent(title+' '+currentUrl)}`,'_blank','noopener');return}if(type==='facebook'){window.open(`https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(currentUrl)}`,'_blank','noopener')}}));

      document.getElementById('newsletterForm')?.addEventListener('submit',e=>{e.preventDefault();const email=document.getElementById('newsletterEmail');if(!email?.checkValidity()){email?.reportValidity();return}showToast('Te-ai abonat la Jurnalul Nordvale.');e.currentTarget.reset()});
    })();
  </script>
</body>
</html>
